import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Dashboard Roadmap","description":"","frontmatter":{"title":"Ceph Dashboard Roadmap","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph Dashboard","distributed storage","monitoring","multicluster","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Dashboard_Roadmap.md","filePath":"posts/2026/Ceph_Dashboard_Roadmap.md","lastUpdated":1780459816000}'),o={name:"posts/2026/Ceph_Dashboard_Roadmap.md"};function l(n,a,s,h,c,d){return i(),t("div",null,[...a[0]||(a[0]=[r('<h2 id="演讲背景" tabindex="-1">演讲背景 <a class="header-anchor" href="#演讲背景" aria-label="Permalink to &quot;演讲背景&quot;">​</a></h2><p>本次演讲来自 Ceph India 社区活动，由 IBM 的 Ceph dashboard 团队成员 Naman 和 Nisam 共同主讲。Nisam 是 IBM 高级软件工程师，在 Ceph dashboard 领域有六年经验，曾担任 dashboard 团队的 component leader。本次分享围绕 Ceph dashboard 的现状、Tentacle 版本新特性、未来规划以及现场 demo 展开。</p><h2 id="当前-dashboard-能力概览" tabindex="-1">当前 Dashboard 能力概览 <a class="header-anchor" href="#当前-dashboard-能力概览" aria-label="Permalink to &quot;当前 Dashboard 能力概览&quot;">​</a></h2><p>Ceph dashboard 目前已是一个功能完整的管理与 monitoring UI，主要能力包括：</p><ul><li>多用户与角色管理（multi-user and role management）</li><li>Single Sign-On（SSO）支持</li><li>SSL/TLS 加密</li><li>审计（auditing）与国际化（internationalization）</li><li>统一 authentication 与 authorization</li><li>集中式日志（centralized logging）</li><li>集中式通知页面（centralized notification page，新引入）</li></ul><p>首页 overview 面板涵盖 inventory 状态、capacity、cluster 利用率及集群详情等核心信息。</p><h2 id="tentacle-版本新特性" tabindex="-1">Tentacle 版本新特性 <a class="header-anchor" href="#tentacle-版本新特性" aria-label="Permalink to &quot;Tentacle 版本新特性&quot;">​</a></h2><h3 id="multicluster-dashboard" tabindex="-1">Multicluster Dashboard <a class="header-anchor" href="#multicluster-dashboard" aria-label="Permalink to &quot;Multicluster Dashboard&quot;">​</a></h3><p>新增独立的 multicluster 管理视图，支持跨集群的添加、删除、编辑操作，可在下拉菜单中快速切换集群，并统一查看 capacity、throughput、IOPS 及 alerts。</p><h3 id="安全增强-oauth2-sso" tabindex="-1">安全增强：OAuth2 SSO <a class="header-anchor" href="#安全增强-oauth2-sso" aria-label="Permalink to &quot;安全增强：OAuth2 SSO&quot;">​</a></h3><p>集成 management gateway，基于 OIDC 协议实现现代化 SSO，支持 MFA（多因素认证），提供统一的集群服务入口，安全性显著提升。</p><h3 id="smb-管理" tabindex="-1">SMB 管理 <a class="header-anchor" href="#smb-管理" aria-label="Permalink to &quot;SMB 管理&quot;">​</a></h3><p>新引入 SMB 管理功能，提供便捷的 SMB cluster 创建与管理界面，支持：</p><ul><li>创建 standalone 用户或 Active Directory 接入</li><li>创建、修改、删除 SMB cluster 及 shares</li><li>集成 Grafana overview dashboard</li></ul><h3 id="rgw-对象存储增强" tabindex="-1">RGW 对象存储增强 <a class="header-anchor" href="#rgw-对象存储增强" aria-label="Permalink to &quot;RGW 对象存储增强&quot;">​</a></h3><p><strong>Multi-site 自动化</strong>：利用 multicluster 配置实现跨集群数据 replication，提供向导式（wizard）UI 流程，支持从零创建新的 multi-site 配置，也支持将现有配置转换为对象 replication。对于未配置 multicluster 的 standalone 场景，提供 token 导入机制。</p><p><strong>Notification Destination</strong>：支持对接 Kafka 或AMQP 等外部服务，可针对 bucket 事件（对象创建、删除等）配置通知规则。</p><p><strong>Storage Class 管理</strong>：支持 cloud S3、cloud S3 Glacier、local 三种 storage class 类型，可通过 dashboard 创建 storage class 配置，并结合 bucket tiering（生命周期策略）实现对象在不同 storage tier 之间的自动 transition。</p><p><strong>用户账户管理（Accounts）</strong>：新增 RGW account 管理，支持创建 account、将用户关联至 account（root 用户或普通用户）、将 bucket 关联至 account，bucket 所有权自动转移至 account。</p><h3 id="nvme-of-tcp-管理" tabindex="-1">NVMe-oF TCP 管理 <a class="header-anchor" href="#nvme-of-tcp-管理" aria-label="Permalink to &quot;NVMe-oF TCP 管理&quot;">​</a></h3><p>按照最新 Carbon Design System 规范完整重构 NVMe TCP 管理界面，UI 更加规范美观，并引入新的 NVMe 向导式配置流程。</p><h3 id="scalability-与-performance-优化" tabindex="-1">Scalability 与 performance 优化 <a class="header-anchor" href="#scalability-与-performance-优化" aria-label="Permalink to &quot;Scalability 与 performance 优化&quot;">​</a></h3><p>这是本版本的重要改进方向：</p><ul><li>优化 API 与网络效率，按需加载前端资源</li><li>减少脚本执行时间（scripting time）与渲染时间</li><li><strong>LCP（Largest Contentful Paint）从 9.82 秒降至 2.11 秒</strong>，达到 2.5 秒以内的 performance 基准，是 dashboard 团队的重要里程碑</li></ul><h3 id="carbon-design-system-迁移" tabindex="-1">Carbon Design System 迁移 <a class="header-anchor" href="#carbon-design-system-迁移" aria-label="Permalink to &quot;Carbon Design System 迁移&quot;">​</a></h3><p>持续将 dashboard 组件从 Bootstrap 迁移至 Carbon Design System，遵循统一的 UX 规范，提升界面一致性与可用性。</p><h3 id="grafana-监控集成" tabindex="-1">Grafana 监控集成 <a class="header-anchor" href="#grafana-监控集成" aria-label="Permalink to &quot;Grafana 监控集成&quot;">​</a></h3><p>新增多个 Grafana 监控 dashboard：</p><ul><li>Multicluster monitoring</li><li>SMB overview</li><li>CephFS overview</li><li>NVMe overview 及 NVMe performance</li><li>Multi-site（应用层）overview</li><li>S3 analytics dashboard</li></ul><h2 id="未来规划" tabindex="-1">未来规划 <a class="header-anchor" href="#未来规划" aria-label="Permalink to &quot;未来规划&quot;">​</a></h2><h3 id="持续进行中" tabindex="-1">持续进行中 <a class="header-anchor" href="#持续进行中" aria-label="Permalink to &quot;持续进行中&quot;">​</a></h3><ul><li>Carbon Design System 迁移：继续将现有 Bootstrap 组件迁移至 Carbon</li><li>REST API 文档完善：补充响应格式说明等缺失文档</li><li>OAuth2 management gateway推广：逐步废弃旧的 SSL配置方式，提供迁移指引</li></ul><h3 id="新-overview-页面" tabindex="-1">新 Overview 页面 <a class="header-anchor" href="#新-overview-页面" aria-label="Permalink to &quot;新 Overview 页面&quot;">​</a></h3><p>基于用户调研反馈，UX 设计师重新设计了 overview 页面，将包含：</p><ul><li>数据弹性（data resiliency）展示，即 PG 状态与数据健康度</li><li>容量消耗趋势（consumption trends）及预测</li><li>性能统计（performance stats）</li><li>系统 alerts 增强展示</li><li>PG 活动专属区域</li></ul><h3 id="cephfs-mirroring" tabindex="-1">CephFS Mirroring <a class="header-anchor" href="#cephfs-mirroring" aria-label="Permalink to &quot;CephFS Mirroring&quot;">​</a></h3><p>引入 CephFS mirroring 功能，补齐 block（RBD）和 RGW multi-site 已有 mirroring 能力的空白，利用 CephFS mirroring 模块实现文件系统级别的数据镜像。</p><h3 id="对象管理视图" tabindex="-1">对象管理视图 <a class="header-anchor" href="#对象管理视图" aria-label="Permalink to &quot;对象管理视图&quot;">​</a></h3><p>提供 RGW bucket 内对象的浏览、上传、删除功能，实现对象级别的管理视图。</p><h3 id="rgw-用户管理增强" tabindex="-1">RGW 用户管理增强 <a class="header-anchor" href="#rgw-用户管理增强" aria-label="Permalink to &quot;RGW 用户管理增强&quot;">​</a></h3><ul><li>改进 IAM policies 管理</li><li>计划将 dashboard 用户与 RGW 用户打通，实现登录后仅查看对应 RGW 用户的 bucket，而非全局 admin 视图</li></ul><h3 id="archive-zone配置" tabindex="-1">Archive Zone配置 <a class="header-anchor" href="#archive-zone配置" aria-label="Permalink to &quot;Archive Zone配置&quot;">​</a></h3><p>支持将 zone 标记为 archive zone 的配置功能。</p><h3 id="nvme-向导流程持续优化" tabindex="-1">NVMe 向导流程持续优化 <a class="header-anchor" href="#nvme-向导流程持续优化" aria-label="Permalink to &quot;NVMe 向导流程持续优化&quot;">​</a></h3><p>根据用户反馈持续改进 NVMe 配置向导，提升端到端配置体验。</p><h2 id="demo-要点回顾" tabindex="-1">Demo 要点回顾 <a class="header-anchor" href="#demo-要点回顾" aria-label="Permalink to &quot;Demo 要点回顾&quot;">​</a></h2><p>现场 demo 覆盖以下流程：</p><ol><li><strong>SMB 管理</strong>：创建 Active Directory 模式和 standalone 用户模式的 SMB cluster，创建 share 并关联 CephFS volume，演示 subvolume 配置</li><li><strong>RGW Accounts管理</strong>：创建 account，创建 root 用户与普通用户，演示 IAM policy（S3 read-only vs S3 full access）对 bucket 操作的权限控制，演示 bucket 与 account 的关联</li><li><strong>Bucket Notification</strong>：配置 Kafka notification destination，创建 bucket notification 配置，上传对象后在 Kafka UI 中验证通知消息接收</li><li><strong>Storage Class 与 Tiering</strong>：创建 cloud S3 storage class，配置生命周期规则（lifecycle rule），观察对象从源集群 transition 至目标集群的完整流程</li></ol><h2 id="联系与参与" tabindex="-1">联系与参与 <a class="header-anchor" href="#联系与参与" aria-label="Permalink to &quot;联系与参与&quot;">​</a></h2><p>团队通过 Ceph 上游社区渠道（IRC、邮件列表等）接受问题反馈，欢迎社区成员参与 Ceph dashboard 的贡献与讨论。</p>',50)])])}const b=e(o,[["render",l]]);export{p as __pageData,b as default};
